def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = 0.0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strong_prev:
                    strong_prev = float(bid)

    if not alive:
        return max(0.0, min(float(budget), 18.0))

    competitors = len(alive) + 1
    tight = supply <= WATER_REQ * 1.5
    roomy = supply >= WATER_REQ * 1.8

    desperate = hp <= 2 or no_water_days >= 2
    fragile = hp <= 4 or no_water_days >= 1

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    top_prev = max(prev_bids) if prev_bids else 52.0

    if desperate:
        bid = max(63.0, top_prev + 4.0)
        if tight:
            bid = max(bid, 72.0)
        return max(0.0, min(float(budget), bid))

    if tight:
        bid = max(56.0, top_prev + 1.5)
        if top_prev >= 85.0:
            bid = 58.0 if hp >= 6 and no_water_days == 0 else 74.0
        elif top_prev >= 70.0:
            bid = max(bid, 61.0)
    elif roomy:
        if hp >= 7 and no_water_days == 0:
            bid = 24.0
        else:
            bid = max(34.0, avg_prev * 0.65)
    else:
        bid = max(42.0, avg_prev * 0.9)
        if top_prev >= 70.0:
            bid = max(bid, 52.0)

    rich = budget >= DAILY_SALARY * (11 - day)
    if not rich:
        bid *= 0.92
    if fragile and bid < 55.0:
        bid = 55.0

    if day >= 8:
        if hp >= 6 and no_water_days == 0 and not tight:
            bid *= 0.9
        elif fragile:
            bid = max(bid, top_prev + 2.0)

    bid = max(0.0, min(float(budget), bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Identify alive opponents and use only yesterday's immediate trace.
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no one is alive, conserve budget.
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids.
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate from yesterday.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply factor: with medium supply (15-25), we can afford moderate bids.
    # Normalize supply to [0,1].
    denom = (MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) != 0 else 1.0
    supply_norm = (float(supply) - MIN_SUPPLY) / denom
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Base bid tuned to compete without matching Eric's very high bids.
    # If opponents previously bid extremely high, slightly increase; otherwise stay moderate.
    if highest_prev_bid >= DAILY_SALARY * 0.75:
        base = DAILY_SALARY * (0.45 + 0.15 * supply_norm)
    else:
        base = DAILY_SALARY * (0.35 + 0.10 * supply_norm)

    # React to our hp: if low, bid more to avoid elimination.
    hp = float(my_status.get('hp', 0))
    if hp <= 1.5:
        base *= 1.25
    elif hp <= 3.0:
        base *= 1.10
    elif hp >= 7.0:
        base *= 0.95

    # If any opponent yesterday ended with 0 budget, assume they were price-sensitive; don't overbid.
    # Use only yesterday trace budget_after if available.
    zero_budget_seen = False
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bud_after = prev.get('budget_after', None)
        try:
            if bud_after is not None and float(bud_after) <= 0.0:
                zero_budget_seen = True
                break
        except Exception:
            pass

    if zero_budget_seen:
        base *= 0.92

    # Ensure we do not exceed our budget.
    budget = float(my_status.get('budget', 0))
    if budget <= 0.0:
        return 0.0

    bid = min(budget, base)

    # Final safety: avoid bidding too low when hp is critical.
    no_water_days = int(my_status.get('no_water_days', 0))
    if hp <= 3.0 and no_water_days >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.6))

    # Clamp to non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)
